import math
from numbers import Real


def _finite_in_range(value, name, minimum, maximum):
    if isinstance(value, bool) or not isinstance(value, Real):
        raise TypeError(f"{name} must be a real number")
    if not math.isfinite(value) or not minimum <= value <= maximum:
        raise ValueError(f"{name} is outside its allowed range")
    return value


class MachineMonitor:
    def __init__(self, load, voltage, vibration):
        self._load = _finite_in_range(load, "load", 0, 100)
        self._voltage = _finite_in_range(voltage, "voltage", 0, 500)
        try:
            axes = list(vibration)
        except TypeError as exc:
            raise TypeError("vibration must be iterable") from exc
        if len(axes) != 3:
            raise ValueError("vibration must contain exactly three values")
        self._vibration = [
            _finite_in_range(value, "vibration value", -20, 20)
            for value in axes
        ]

    def read_load(self):
        return self._load

    def read_voltage(self):
        return self._voltage

    def read_vibration(self):
        return list(self._vibration)

    def read_all(self):
        return {
            "load": self._load,
            "voltage": self._voltage,
            "vibration": self._vibration,
        }

